$ErrorActionPreference = 'Stop'
function Need($ok,[string]$why) { if (!$ok) { throw $why } }
function Sha([byte[]]$bytes) {
    $hash = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($hash.ComputeHash($bytes))).Replace('-','').ToLowerInvariant() }
    finally { $hash.Dispose() }
}
Need ($env:OS -eq 'Windows_NT') 'WINDOWS_REQUIRED'
Need ([Environment]::Is64BitProcess) 'POWERSHELL_X64_REQUIRED'
Need (!(Get-Process -Name CabalMain -ErrorAction SilentlyContinue)) 'AIZVER_SPELI_PIRMS_ATJAUNINAJUMA'
$folder = Join-Path $env:USERPROFILE ('Downloads\Client291-Pet-v1-'+[guid]::NewGuid().ToString('N').Substring(0,8))
[void][IO.Directory]::CreateDirectory($folder)
[byte[]]$zip = [Convert]::FromBase64String('')
Need ((Sha $zip) -eq '658a5ca2722201a3df991949b023f7159b379cc0627bf79bbe80c2a4fc03c442') 'CLIENT_PACKAGE_HASH_DIFFERS'
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem
$memory = [IO.MemoryStream]::new($zip)
$archive = [IO.Compression.ZipArchive]::new($memory,[IO.Compression.ZipArchiveMode]::Read)
try {
    foreach ($entry in $archive.Entries) {
        Need ($entry.FullName -match '^[A-Za-z0-9_.-]+$' -and $entry.Length -lt 1048576) 'CLIENT_PACKAGE_MEMBER_INVALID'
        $stream = $entry.Open()
        $buffer = [IO.MemoryStream]::new()
        try {
            $stream.CopyTo($buffer)
            [IO.File]::WriteAllBytes((Join-Path $folder $entry.FullName),$buffer.ToArray())
        } finally { $stream.Dispose(); $buffer.Dispose() }
    }
} finally { $archive.Dispose(); $memory.Dispose() }
$hashes = Get-Content -Raw -LiteralPath (Join-Path $folder 'hashes.json') | ConvertFrom-Json
foreach ($file in $hashes.PSObject.Properties) {
    Need ((Get-FileHash -LiteralPath (Join-Path $folder $file.Name)).Hash -eq $file.Value) ('CLIENT_FILE_DIFFERS_'+$file.Name)
}
$compiler = Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe'
Need (Test-Path -LiteralPath $compiler) 'WINDOWS_COMPILER_MISSING'
$launcher = Join-Path $folder 'Launcher.exe'
$automation = [System.Management.Automation.PowerShell].Assembly.Location
& $compiler /nologo /target:exe /platform:x64 /optimize+ ("/reference:"+$automation) ("/out:"+$launcher) (Join-Path $folder 'LauncherHost.cs')
Need ($LASTEXITCODE -eq 0 -and (Test-Path -LiteralPath $launcher)) 'LAUNCHER_BUILD_FAILED'
(Get-FileHash -LiteralPath $launcher).Hash | Set-Content -LiteralPath (Join-Path $folder 'launcher-sha.txt') -Encoding ascii
$runner = @'
$ErrorActionPreference='Stop'
if(Get-Process -Name CabalMain -ErrorAction SilentlyContinue){throw 'CABAL_JAU_PALAISTS'}
$hashes=Get-Content -Raw -LiteralPath (Join-Path $PSScriptRoot 'hashes.json') | ConvertFrom-Json
foreach($file in $hashes.PSObject.Properties){
 if((Get-FileHash -LiteralPath (Join-Path $PSScriptRoot $file.Name)).Hash -ne $file.Value){throw ('CLIENT_FILE_DIFFERS_'+$file.Name)}
}
$launcher=Join-Path $PSScriptRoot 'Launcher.exe'
$expected=(Get-Content -Raw -LiteralPath (Join-Path $PSScriptRoot 'launcher-sha.txt')).Trim()
if((Get-FileHash -LiteralPath $launcher).Hash -ne $expected){throw 'LAUNCHER_HASH_DIFFERS'}
Start-Process -FilePath $launcher -WorkingDirectory $PSScriptRoot -Verb RunAs
'@
[IO.File]::WriteAllText((Join-Path $folder 'Palaist-Pet291.ps1'),$runner,[Text.Encoding]::ASCII)
$cmd = [string]::Join([Environment]::NewLine,@('@echo off','cd /d "%~dp0"','powershell.exe -NoProfile -ExecutionPolicy Bypass -File "%~dp0Palaist-Pet291.ps1"','if errorlevel 1 pause',''))
[IO.File]::WriteAllText((Join-Path $folder 'Palaist-Pet291.cmd'),$cmd,[Text.Encoding]::ASCII)
'PET_KLIENTS_SAGATAVOTS='+$folder
[byte[]]$serverBytes = [Convert]::FromBase64String('')
Need ((Sha $serverBytes) -eq '1663b884e963abe42eedc52c2eaa7e384e045e1e4bbebf74964301501d6d4026') 'SERVER_PACKAGE_HASH_DIFFERS'
[Text.Encoding]::ASCII.GetString($serverBytes) | ssh root@192.168.56.101 python3 - --apply
Need ($LASTEXITCODE -eq 0) 'PET_SERVER_INSTALL_NOT_CONFIRMED; ATSUTI_IZVADI'
'PET_PURCHASE_TEST_READY; MILEAGE_PRICE=50; PHYSICAL_REGISTER_PENDING'
'PALAISANA='+ (Join-Path $folder 'Palaist-Pet291.cmd')
